using System.IO.Compression;
using System.Runtime.InteropServices;
using System.Text;
using OfficeIMO.Excel;

if (RuntimeInformation.ProcessArchitecture != Architecture.Wasm)
    throw new InvalidOperationException("This regression requires the WebAssembly runtime.");
const int rowCount = 6000;
string padding = new string('x', 256);
const string expectedSuffix = " & < > \" ' &amp; &#13;";
using (var workbook = CreateWorkbook(null)) {
    using var reader = ExcelDocument.OpenReader(workbook);
    for (int row = 1; row <= rowCount; row++) {
        if (!reader.Read() || reader.GetInt32(0) != row || reader.GetString(1) != "Label " + row + padding + expectedSuffix)
            throw new InvalidDataException("Unexpected row content at " + row);
    }
    if (reader.Read()) throw new InvalidDataException("Unexpected extra row.");
}
foreach (string failure in new[] { "SharedString", "Entity" }) {
    bool rejected = false;
    using var workbook = CreateWorkbook(failure);
    try { using var reader = ExcelDocument.OpenReader(workbook); reader.Read(); }
    catch (InvalidDataException) when (failure == "SharedString") { rejected = true; }
    catch (System.Xml.XmlException) when (failure == "Entity") { rejected = true; }
    if (!rejected) throw new InvalidOperationException("Late " + failure + " was not rejected before first-row exposure.");
}
Console.WriteLine("PASS: Wasm compressed reader returns every escaped value and rejects late invalid shared strings and entities before exposure.");

MemoryStream CreateWorkbook(string? invalidTail) {
    var result = new MemoryStream();
    using (var zip = new ZipArchive(result, ZipArchiveMode.Create, leaveOpen: true)) {
        Add("[Content_Types].xml", "<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/></Types>");
        Add("_rels/.rels", "<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");
        Add("xl/workbook.xml", "<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"Data\" sheetId=\"1\" r:id=\"rId1\"/></sheets></workbook>");
        Add("xl/_rels/workbook.xml.rels", "<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet1.xml\"/></Relationships>");
        var xml = new StringBuilder("<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData><row><c t=\"str\"><v>Id</v></c><c t=\"str\"><v>Label</v></c></row>");
        for (int row = 1; row <= rowCount; row++) {
            xml.Append("<row><c><v>").Append(row).Append("</v></c>");
            if (invalidTail == "SharedString" && row == rowCount) xml.Append("<c t=\"s\"><v>2147483647</v></c>");
            else {
                xml.Append("<c t=\"inlineStr\"><is><t>Label ").Append(row).Append(padding)
                    .Append(" &amp; &lt; &gt; &quot; &apos; &amp;amp; &amp;#13;");
                if (invalidTail == "Entity" && row == rowCount) xml.Append("&unknown;");
                xml.Append("</t></is></c>");
            }
            xml.Append("</row>");
        }
        xml.Append("</sheetData></worksheet>");
        if (xml.Length <= 1_048_576) throw new InvalidOperationException("Fixture must cross the compression/index overlap threshold.");
        Add("xl/worksheets/sheet1.xml", xml.ToString());
        void Add(string path, string content) {
            using var writer = new StreamWriter(zip.CreateEntry(path, CompressionLevel.Optimal).Open(), new UTF8Encoding(false));
            writer.Write(content);
        }
    }
    result.Position = 0;
    return result;
}
